<section class="page-head"><div><p class="eyebrow">Comercial</p><h1>Vendas</h1><p>Projetos aprovados com contato do lead e link de pagamento.</p></div></section>
<?php if ($success): ?><div class="alert alert-success" role="status">Ação comercial registrada.</div><?php endif; ?>
<?php if (is_string($error) && $error !== ''): ?><div class="alert alert-error" role="alert"><?= e($error) ?></div><?php endif; ?>
<div class="card-grid"><?php if ($sales === []): ?><p class="empty">Nenhum projeto disponível para venda.</p><?php endif; ?><?php foreach ($sales as $sale): ?><article class="work-card"><span class="status"><?= e($sale['status']) ?></span><h2><?= e($sale['projeto_nome']) ?></h2><p><strong>Lead:</strong> <?= e($sale['lead_nome']) ?></p><p><?= e($sale['contatos'] ?? 'Sem contato') ?></p><p><strong>Valor:</strong> R$ <?= e(number_format((float) $sale['valor_brl'], 2, ',', '.')) ?></p><div class="actions"><a class="button button-secondary" href="<?= e($sale['url_preview']) ?>" target="_blank" rel="noopener noreferrer">Ver projeto</a><a class="button button-primary" href="<?= e($sale['link_pagamento']) ?>" target="_blank" rel="noopener noreferrer">Pagamento</a></div>
<?php if ($sale['status'] === 'disponivel'): ?><form method="post" action="/sales/claim"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="sale_uuid" value="<?= e($sale['uuid']) ?>"><button class="button button-primary button-wide" type="submit">Assumir venda</button></form>
<?php else: ?><form class="stack" method="post" action="/sales/contact"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="sale_uuid" value="<?= e($sale['uuid']) ?>"><label class="field"><span>Canal</span><select name="channel"><option value="whatsapp">WhatsApp</option><option value="email">E-mail</option><option value="instagram">Instagram</option><option value="telefone">Telefone</option><option value="outro">Outro</option></select></label><label class="field"><span>Resultado</span><select name="result"><option value="contato_realizado">Contato realizado</option><option value="retorno_agendado">Retorno agendado</option><option value="aguardando_pagamento">Aguardando pagamento</option><option value="perdido">Perdido</option></select></label><label class="field"><span>Próximo contato</span><input type="datetime-local" name="next_contact_at"></label><label class="field"><span>Observações</span><textarea name="notes" rows="3"></textarea></label><button class="button button-primary" type="submit">Registrar atendimento</button></form><?php endif; ?></article><?php endforeach; ?></div>
